head.script:
///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function() {
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name dts_ComList_OnLoadError
 * @description dts_ComList 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_ComList_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_ComList);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDFIS00101.dts_ComList_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_ComList_OnLoadCompleted
 * @description dts_ComList 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_ComList_OnLoadCompleted = function(rowcount) {
    try {
        if (dts_ComList.errorMsg) {
            alert(dts_ComList.errorMsg);
        } else {
            txb_TotCnt.setValue("총 " + rowcount + " 건");
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDFIS00101.dts_ComList_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name grd_ComList_OnDblClick
 * @description grd_ComList 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_ComList_OnDblClick = async function(row, colid) {
    try {
        await scwin.setParam(row);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDFIS00101.grd_ComList_OnDblClick" });
    }
};

/**
 * @method
 * @name btn_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search_onclick = async function() {
    try {
        // 조회 버튼 클릭
        await scwin.search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDFIS00101.btn_Search_onclick" });
    }
};

/**
 * @method
 * @name img_Confirm_onclick
 * @description 「확인」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_Confirm_onclick = async function() {
    try {
        // 확인버튼 클릭
        await scwin.setParam();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDFIS00101.img_Confirm_onclick" });
    }
};

/**
 * @method
 * @name img_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_Close_onclick = async function() {
    try {
        // 닫기 버튼 클릭
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDFIS00101.img_Close_onclick" });
    }
};

/**
 * @method
 * @name txb_CoSnm_onkeydown
 * @description txb_CoSnm 키 입력 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.txb_CoSnm_onkeydown = async function() {
    try {
        // 기업명 엔터
        if (event.keyCode === 13) {
            await scwin.search();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDFIS00101.txb_CoSnm_onkeydown" });
    }
};

/**
 * @method
 * @name img_StdIndCd_onclick
 * @description img_StdIndCd 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_StdIndCd_onclick = async function() {
    try {
        // 업종검색 팝업 오픈
        await scwin.stdIndSrchOpen();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDFIS00101.img_StdIndCd_onclick" });
    }
};

/**
 * @method
 * @name img_AffCoCd_onclick
 * @description img_AffCoCd 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_AffCoCd_onclick = async function() {
    try {
        // 기업집단검색 팝업 오픈
        await scwin.affCoCdSrchOpen();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDFIS00101.img_AffCoCd_onclick" });
    }
};

/**
 * @method
 * @name txb_EntprGrpNm_onkeydown
 * @description txb_EntprGrpNm 키 입력 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.txb_EntprGrpNm_onkeydown = async function() {
    try {
        // 기업집단검색 팝업 오픈
        if (event.keyCode === 13) {
            await scwin.affCoCdSrchOpen();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDFIS00101.txb_EntprGrpNm_onkeydown" });
    }
};

/**
 * @method
 * @name txb_EntprGrpNm_onchange
 * @description txb_EntprGrpNm 변경 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_EntprGrpNm_onchange = function() {
    try {
        txb_EntprGrpCd.setValue("");
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDFIS00101.txb_EntprGrpNm_onchange" });
    }
};

/**
 * @method
 * @name txb_StdIndNm_onchange
 * @description txb_StdIndNm 변경 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_StdIndNm_onchange = function() {
    try {
        txb_StdIndCd.setValue("");
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDFIS00101.txb_StdIndNm_onchange" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name search
 * @description 기업목록 조회
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function() {
    // 데이터셋 초기화
    scwin.initDs();

    // 조회조건 필수 체크.
    if (!scwin.chkValid()) {
        return;
    }

    // Lodaing~~~ 표시
    const sbmOptions = {
        id : "sbm_dts_ComList",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_ComList=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name popupCallback
 * @description browserPopup 팝업의 callback 함수. 부모창에서 팝업 결과 값을 처리한다.
 * @param {*} arg 팝업에서 전달받은 값
 * @returns {void}
 * @hidden N
 */
scwin.popupCallback = function (arg) {
    // TO-DO : arg 값 확인 후 업무 로직 추가
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name initDs
 * @description 데이터셋 초기화.
 * @returns {void}
 * @hidden N
 */
scwin.initDs = function() {
    dts_ComList.removeAll();
    txb_TotCnt.setValue("");
};

/**
 * @method
 * @name chkValid
 * @description 조회조건 유효성 체크
 * @returns {void}
 * @hidden N
 */
scwin.chkValid = function() {
    // 필수항목 체크.
    if (txb_CoSnm.getValue() === "" && cmb_CorpRegTyp.getValue() === "" && txb_StdIndCd.getValue() === "" && txb_EntprGrpCd.getValue() === "") {
        alert("조회조건을 입력하세요.");
        txb_CoSnm.focus();
        return false;
    }
    return true;
};

/**
 * @method
 * @name setParam
 * @description 선택된 값을 오프너에 전달한다.
 * @param {*} v_Currow v_Currow
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setParam = async function(v_Currow) {
    if (v_Currow === undefined) {
        v_Currow = dts_ComList.getRowPosition();
    }
    let arrPar = new Array();
    arrPar[0] = {
        CO_SNM: dts_ComList.getCellData(v_Currow, "CO_SNM"), // 기업명
        KIS_CD: dts_ComList.getCellData(v_Currow, "KIS_CD"), // 기업코드
        IND_PTTN: dts_ComList.getCellData(v_Currow, "IND_PTTN") // 업종유형
    };

    opener.fn_SetParKisCd(arrPar);
    await $c.win.closePopup();
};

/**
 * @method
 * @name stdIndSrchOpen
 * @description 업종검색 팝업 오픈
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.stdIndSrchOpen = async function() {
    const options = {
        id: "ULDFIS00100_P2",
        title: "업종검색",
        type: "browserPopup",
        width: 360 + 20,
        height: 460 + 40,
        callbackFn: "scwin.popupCallback"
    };

    $c.win.openPopup("./ULDFIS00100_P2.gfm", options);
};

/**
 * @method
 * @name getParStdIndCd
 * @description 업종검색 팝업으로 값을 넘김.
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.getParStdIndCd = function(arrPar) {

};

/**
 * @method
 * @name setParStdIndCd
 * @description 업종검색 팝업에서 값을 받음.
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.setParStdIndCd = function(arrPar) {
    txb_StdIndCd.setValue(arrPar[0].STD_IND_CD); // 업종코드
    txb_StdIndNm.setValue(arrPar[0].STD_IND_NM); // 업종명

};

/**
 * @method
 * @name affCoCdSrchOpen
 * @description 기업집단검색 팝업 오픈
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.affCoCdSrchOpen = async function() {
    const options = {
        id: "ULDFIS00100_P3",
        title: "기업집단검색",
        type: "browserPopup",
        width: 226 + 20,
        height: 320 + 40,
        callbackFn: "scwin.popupCallback"
    };

    $c.win.openPopup("./ULDFIS00100_P3.gfm", options);
};

/**
 * @method
 * @name getParAffCoCd
 * @description 기업집단검색 팝업으로 값을 넘김.
 * @returns {void}
 * @hidden N
 */
scwin.getParAffCoCd = function() {
    let arrPar = new Array();
    arrPar[0] = txb_EntprGrpNm.getValue(); // 기업집단
    return arrPar;
};

/**
 * @method
 * @name setParAffCoCd
 * @description 기업집단검색 팝업에서 값을 받음.
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.setParAffCoCd = function(arrPar) {
    txb_EntprGrpCd.setValue(arrPar[0].ENTPR_GRP_CD); // 기업집단코드
    txb_EntprGrpNm.setValue(arrPar[0].ENTPR_GRP_NM); // 기업집단명

};

/**
 * @method
 * @name gform_onload
 * @description gform onload 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.gform_onload = async function() {
    $c.cm.PanelToGroupBox(panel_Top); // 패널라운드 처리

    let arrPar = opener.fn_GetParKisCd();
    txb_CoSnm.setValue((arrPar.length > 0) ? arrPar[0] : "");
    if (txb_CoSnm.getValue() !== "") {
        await scwin.search();
    } else {
        txb_CoSnm.focus();
    }
};
